// rustorb C++ implementation of the InteropTest client, with stubs and
// skeletons generated by rustorb-idl -bc++11.
//
// Resolves the Echo object from the naming service, runs every test case
// against it and exits non-zero if any case fails.

#include <sstream>

#define ANYTEST_HIDDEN
#include "anytest.h"
#include "cases.h"
#include "common.h"
#include "customtest.h"
#include "valuetest.h"

// The stage 2 suite (AnyTest.idl) against the AnyEcho object at opt.name;
// the server's Echo object is at opt.name + "-Echo".
static int run_any(IDL::traits<CORBA::ORB>::ref_type orb,
                   IDL::traits<CosNaming::NamingContext>::ref_type root, const Options& opt) {
  CosNaming::Name name = to_name(opt.name);
  auto obj = retry("the AnyEcho server", [&]() { return root->resolve(name); }, opt.timeout);
  auto echo = IDL::traits<AnyTest::AnyEcho>::narrow(obj);
  if (!echo) {
    std::cout << opt.name << " is not an AnyTest::AnyEcho" << std::endl;
    return 1;
  }
  retry("the AnyEcho server", [&]() { return echo->_non_existent(); }, opt.timeout);

  Runner r;
  anytest::run_cases(r, echo, [](bool cond, const std::string& what) {
    if (!cond) throw CheckFailed{what};
  });

  if (opt.shutdown_server) {
    auto server = IDL::traits<InteropTest::Echo>::narrow(root->resolve(to_name(opt.name + "-Echo")));
    server->shutdown();
  }

  r.summary();
  orb->destroy();
  return r.failed().empty() ? 0 : 1;
}

// The valuetype suite (ValueTest.idl) against the ValueEcho object at
// opt.name.
static int run_value(IDL::traits<CORBA::ORB>::ref_type orb,
                     IDL::traits<CosNaming::NamingContext>::ref_type root, const Options& opt) {
  valuetest::register_factories(orb);
  CosNaming::Name name = to_name(opt.name);
  auto obj = retry("the ValueEcho server", [&]() { return root->resolve(name); }, opt.timeout);
  auto echo = IDL::traits<ValueTest::ValueEcho>::narrow(obj);
  if (!echo) {
    std::cout << opt.name << " is not a ValueTest::ValueEcho" << std::endl;
    return 1;
  }
  retry("the ValueEcho server", [&]() { return echo->_non_existent(); }, opt.timeout);

  Runner r;
  valuetest::run_cases(r, echo, [](bool cond, const std::string& what) {
    if (!cond) throw CheckFailed{what};
  });

  if (opt.shutdown_server) echo->shutdown();

  r.summary();
  orb->destroy();
  return r.failed().empty() ? 0 : 1;
}

// The custom valuetype suite (CustomTest.idl) against the CustomEcho
// object at opt.name.
static int run_custom(IDL::traits<CORBA::ORB>::ref_type orb,
                      IDL::traits<CosNaming::NamingContext>::ref_type root, const Options& opt) {
  customtest::register_factories(orb);
  CosNaming::Name name = to_name(opt.name);
  auto obj = retry("the CustomEcho server", [&]() { return root->resolve(name); }, opt.timeout);
  auto echo = IDL::traits<CustomTest::CustomEcho>::narrow(obj);
  if (!echo) {
    std::cout << opt.name << " is not a CustomTest::CustomEcho" << std::endl;
    return 1;
  }
  retry("the CustomEcho server", [&]() { return echo->_non_existent(); }, opt.timeout);

  Runner r;
  customtest::run_cases(r, echo, [](bool cond, const std::string& what) {
    if (!cond) throw CheckFailed{what};
  });

  if (opt.shutdown_server) echo->shutdown();

  r.summary();
  orb->destroy();
  return r.failed().empty() ? 0 : 1;
}

int main(int argc, char** argv) {
  std::vector<std::string> orb_args;
  Options opt = parse_args(argc, argv, orb_args);
  try {
    auto orb = orb_init(orb_args);
    auto poa = persistent_poa(orb, "InteropTestClient");

    auto root = root_context(orb, opt.timeout);
    if (opt.suite == "any") return run_any(orb, root, opt);
    if (opt.suite == "value") return run_value(orb, root, opt);
    if (opt.suite == "custom") return run_custom(orb, root, opt);
    CosNaming::Name name = to_name(opt.name);
    auto obj = retry("the Echo server", [&]() { return root->resolve(name); }, opt.timeout);
    auto echo = IDL::traits<InteropTest::Echo>::narrow(obj);
    if (!echo) {
      std::cout << opt.name << " is not an InteropTest::Echo" << std::endl;
      return 1;
    }
    retry("the Echo server", [&]() { return echo->_non_existent(); }, opt.timeout);

    Runner r;
    run_cases(r, echo, poa);

    if (opt.shutdown_server) echo->shutdown();

    r.summary();
    orb->destroy();
    return r.failed().empty() ? 0 : 1;
  } catch (const CORBA::Exception& e) {
    std::cerr << "CORBA exception: " << e << std::endl;
    return 1;
  }
}
